<script lang="ts">
  import { onMount, tick } from 'svelte';
  import { ArrowRight, BarChart3, Box, ChevronRight, Clock3, CreditCard, FileText, Menu, Package, Plus, Search, ShoppingCart, Trash2, Wallet, X } from '@lucide/svelte';
  import { activities, addExpense, addProduct, addStock, businessDay, closeDay, createSale, expenses, initStore, isDemo, online, openDay, products, sales, stockEntries, refresh, reopenDay } from '../lib/store';
  import { money, rwf, shortDate, today } from '../lib/format';
  import { supabase } from '../lib/supabase';
  import type { CartLine, PaymentMethod, Product } from '../lib/types';

  type Page = 'sale' | 'sales' | 'inventory' | 'expenses' | 'reports' | 'activity';
  let page: Page = $state('sale');
  let railOpen = $state(false);
  let search = $state('');
  let searchInput: HTMLInputElement = $state()!;
  let cart: CartLine[] = $state([]);
  let paymentOpen = $state(false);
  let payment: Record<PaymentMethod, number> = $state({ cash: 0, momo: 0, bank: 0 });
  let working = $state(false);
  let error = $state('');
  let success = $state('');
  let startDayOpen = $state(false);
  let priceDraft: Record<string, number> = $state({});
  let reopenReason = $state('');
  let inventoryTab: 'products' | 'history' | 'balances' = $state('products');
  let stockDrawer = $state(false);
  let productDrawer = $state(false);
  let stockForm = $state({ productId: '', quantity: 1, unitCost: 0, supplier: '', paid: 0, note: '' });
  let productForm = $state({ name: '', category: '', unit: '25 kg sack', price: 0 });
  let expenseForm = $state({ category: 'Transport', description: '', amount: 0, method: 'cash' as PaymentMethod });
  let dragProgress = $state(0);
  let dragging = $state(false);
  let sliderElement: HTMLDivElement = $state()!;
  let userEmail = $state('');
  let password = $state('');
  let authMode: 'signin' | 'signup' | 'reset' = $state('signin');
  let authenticated = $state(isDemo);

  onMount(() => {
    initStore();
    void tick().then(() => searchInput?.focus());
    if (supabase) {
      void supabase.auth.getSession().then(({ data }) => { authenticated = !!data.session; if (data.session) void refresh(); });
      const { data } = supabase.auth.onAuthStateChange((_event, session) => authenticated = !!session);
      return () => data.subscription.unsubscribe();
    }
  });

  let activeProducts = $derived($products.filter((p) => p.active && `${p.name} ${p.category} ${p.unit}`.toLowerCase().includes(search.toLowerCase())));
  let total = $derived(cart.reduce((sum, l) => sum + l.quantity * l.unitPrice, 0));
  let paid = $derived(payment.cash + payment.momo + payment.bank);
  let remaining = $derived(Math.max(0, total - paid));
  let canConfirm = $derived(cart.length > 0 && remaining === 0 && paid === total && !working);
  let dayIsOpen = $derived($businessDay?.status === 'open' && $businessDay?.date === today());
  let daySales = $derived($sales.filter((s) => new Intl.DateTimeFormat('en-CA', { timeZone: 'Africa/Kigali' }).format(new Date(s.at)) === today()));
  let dayExpenses = $derived($expenses.filter((e) => new Intl.DateTimeFormat('en-CA', { timeZone: 'Africa/Kigali' }).format(new Date(e.at)) === today()));
  let revenue = $derived(daySales.reduce((sum, s) => sum + s.total, 0));
  let cost = $derived(daySales.reduce((sum, s) => sum + s.cost, 0));
  let expenseTotal = $derived(dayExpenses.reduce((sum, e) => sum + e.amount, 0));
  let profit = $derived(revenue - cost - expenseTotal);
  let profitVerified = $derived(daySales.every((s) => !s.hasCostDeficit && s.source === 'supabase'));
  let balances = $derived([...new Set($stockEntries.map((entry) => entry.supplier).filter(Boolean))].map((supplier) => ({ supplier, due: $stockEntries.filter((e) => e.supplier === supplier).reduce((sum, e) => sum + e.quantity * e.unitCost - e.paid, 0) })));

  function selectPage(value: Page) { page = value; railOpen = false; error = ''; paymentOpen = false; }
  function addToCart(product: Product) {
    if (!dayIsOpen) { startDay(); return; }
    const existing = cart.find((line) => line.productId === product.id);
    cart = existing ? cart.map((line) => line.productId === product.id ? { ...line, quantity: line.quantity + 1 } : line) : [...cart, { productId: product.id, quantity: 1, unitPrice: product.price }];
    search = '';
    void tick().then(() => document.querySelector<HTMLInputElement>(`[data-qty="${product.id}"]`)?.focus());
  }
  function updateLine(productId: string, field: 'quantity' | 'unitPrice', value: string) { cart = cart.map((line) => line.productId === productId ? { ...line, [field]: Math.max(0, Math.round(Number(value) || 0)) } : line); }
  function removeLine(productId: string) { cart = cart.filter((line) => line.productId !== productId); }
  function startDay() { priceDraft = Object.fromEntries($products.map((p) => [p.id, p.price])); startDayOpen = true; }
  async function submitDay() { try { working = true; error = ''; if ($businessDay?.date === today() && $businessDay.status === 'closed') { await reopenDay(reopenReason); success = 'Business day reopened'; } else { await openDay(priceDraft); success = 'Business day opened'; } startDayOpen = false; reopenReason = ''; } catch (e) { error = message(e); } finally { working = false; } }
  async function submitCloseDay() { if (!confirm('Close today’s business day?')) return; try { working = true; await closeDay(); success = 'Business day closed'; } catch (e) { error = message(e); } finally { working = false; } }
  async function finishSale() {
    if (!canConfirm) return;
    try { working = true; error = ''; const saleId = await createSale(cart, Object.entries(payment).filter(([, amount]) => amount > 0).map(([method, amount]) => ({ method: method as PaymentMethod, amount }))); success = `Sale ${saleId.slice(0, 8)} completed · ${rwf(total)}`; cart = []; payment = { cash: 0, momo: 0, bank: 0 }; paymentOpen = false; dragProgress = 0; void tick().then(() => searchInput?.focus()); }
    catch (e) { error = message(e); dragProgress = 0; } finally { working = false; }
  }
  async function submitStock() { try { working = true; error = ''; await addStock(stockForm); stockDrawer = false; stockForm = { productId: '', quantity: 1, unitCost: 0, supplier: '', paid: 0, note: '' }; success = 'Stock received'; } catch (e) { error = message(e); } finally { working = false; } }
  async function submitProduct() { try { working = true; error = ''; await addProduct(productForm); productDrawer = false; productForm = { name: '', category: '', unit: '25 kg sack', price: 0 }; success = 'Product created'; } catch (e) { error = message(e); } finally { working = false; } }
  async function submitExpense() { try { working = true; error = ''; await addExpense(expenseForm); expenseForm = { category: 'Transport', description: '', amount: 0, method: 'cash' }; success = 'Expense recorded'; } catch (e) { error = message(e); } finally { working = false; } }
  async function auth() {
    if (!supabase) return;
    try { working = true; error = '';
      if (authMode === 'reset') { const { error: e } = await supabase.auth.resetPasswordForEmail(userEmail); if (e) throw e; success = 'Password reset email sent'; }
      else if (authMode === 'signup') { const { error: e } = await supabase.auth.signUp({ email: userEmail, password }); if (e) throw e; success = 'Check your email to confirm your account'; }
      else { const { error: e } = await supabase.auth.signInWithPassword({ email: userEmail, password }); if (e) throw e; await refresh(); }
    } catch (e) { error = message(e); } finally { working = false; }
  }
  function message(e: unknown) { return e instanceof Error ? e.message : String(e); }
  function exportCsv() { const rows = [['Date', 'Sale ID', 'Total RWF', 'Cost RWF', 'Profit RWF', 'Payments'], ...$sales.map((s) => [s.at, s.id, s.total, s.cost, s.total - s.cost, s.payments.map((p) => `${p.method}:${p.amount}`).join(' | ')])]; const csv = rows.map((row) => row.map((cell) => `"${String(cell).replaceAll('"', '""')}"`).join(',')).join('\n'); const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' })); const a = document.createElement('a'); a.href = url; a.download = `sales-${today()}.csv`; a.click(); URL.revokeObjectURL(url); }
  function pointerDown(event: PointerEvent) { if (!canConfirm) return; dragging = true; sliderElement.setPointerCapture(event.pointerId); pointerMove(event); }
  function pointerMove(event: PointerEvent) { if (!dragging) return; const rect = sliderElement.getBoundingClientRect(); dragProgress = Math.max(0, Math.min(1, (event.clientX - rect.left - 27) / (rect.width - 54))); }
  function pointerUp() { if (!dragging) return; dragging = false; if (dragProgress > 0.88) void finishSale(); else dragProgress = 0; }
</script>

<svelte:head><title>Stock Manager — Wholesale POS</title><meta name="description" content="Wholesale sales, inventory and daily profit in one focused workspace." /></svelte:head>

{#if !authenticated}
  <main class="auth-page"><form class="auth-card" onsubmit={(e) => { e.preventDefault(); void auth(); }}><div class="brand-mark"><Box size={24} /></div><h1>{authMode === 'signin' ? 'Welcome back' : authMode === 'signup' ? 'Create your account' : 'Reset password'}</h1><p>Sign in to your wholesale workspace.</p><label>Email<input type="email" bind:value={userEmail} autocomplete="email" required /></label>{#if authMode !== 'reset'}<label>Password<input type="password" bind:value={password} autocomplete={authMode === 'signup' ? 'new-password' : 'current-password'} required minlength="6" /></label>{/if}{#if error}<div class="notice danger">{error}</div>{/if}{#if success}<div class="notice">{success}</div>{/if}<button class="primary" disabled={working}>{authMode === 'signin' ? 'Sign in' : authMode === 'signup' ? 'Create account' : 'Send reset email'} <ArrowRight size={18} /></button><div class="auth-links"><button type="button" onclick={() => authMode = authMode === 'signup' ? 'signin' : 'signup'}>{authMode === 'signup' ? 'Sign in' : 'Create account'}</button><button type="button" onclick={() => authMode = authMode === 'reset' ? 'signin' : 'reset'}>{authMode === 'reset' ? 'Back' : 'Forgot password?'}</button></div></form></main>
{:else}
  <div class="app-shell"><aside class:expanded={railOpen} class="rail"><button class="rail-brand" title="Toggle menu" aria-label="Toggle menu" onclick={() => railOpen = !railOpen}><Box size={24} /></button><nav aria-label="Main navigation"><button class:active={page === 'sale'} title="New sale" onclick={() => selectPage('sale')}><ShoppingCart size={23} /><span>New sale</span></button><button class:active={page === 'sales'} title="Sales" onclick={() => selectPage('sales')}><FileText size={23} /><span>Sales</span></button><button class:active={page === 'inventory'} title="Inventory" onclick={() => selectPage('inventory')}><Package size={23} /><span>Inventory</span></button><button class:active={page === 'expenses'} title="Expenses" onclick={() => selectPage('expenses')}><CreditCard size={23} /><span>Expenses</span></button><button class:active={page === 'reports'} title="Reports" onclick={() => selectPage('reports')}><BarChart3 size={23} /><span>Reports</span></button><button class:active={page === 'activity'} title="Activity" onclick={() => selectPage('activity')}><Clock3 size={23} /><span>Activity</span></button></nav><button class="rail-bottom" title="Expand menu" aria-label="Expand menu" onclick={() => railOpen = !railOpen}><Menu size={21} /><span>Menu</span></button></aside>
    <main class="workspace"><header class="topbar"><h1>{page === 'sale' ? 'New sale' : page === 'sales' ? 'Sales' : page === 'inventory' ? 'Inventory' : page === 'expenses' ? 'Expenses' : page === 'reports' ? 'Reports' : 'Activity'}</h1><div class="status"><button class="status-button" onclick={dayIsOpen ? submitCloseDay : startDay}><i class:off={!dayIsOpen}></i>{dayIsOpen ? 'Day open' : 'Start day'}</button><span class="status-divider"></span><span><i class:off={!$online}></i>{$online ? 'Online' : 'Offline'}</span>{#if isDemo}<span class="demo-pill">Demo mode</span>{/if}</div></header>
    {#if error}<div class="banner danger" role="alert">{error}<button aria-label="Dismiss" onclick={() => error = ''}><X size={17} /></button></div>{/if}{#if success}<div class="banner success" role="status">{success}<button aria-label="Dismiss" onclick={() => success = ''}><X size={17} /></button></div>{/if}
    {#if page === 'sale'}
      <div class:payment-visible={paymentOpen} class="sale-layout"><section class="panel products-panel"><h2>Products</h2><div class="search-wrap"><Search size={24} /><input bind:this={searchInput} bind:value={search} placeholder="Search products" aria-label="Search products" /></div><div class="product-head"><span>Product</span><span>Stock</span><span>Today’s price (RWF)</span></div><div class="product-list">{#each activeProducts as product}<button class="product-row" onclick={() => addToCart(product)}><span class="product-name"><strong>{product.name}</strong><small>{product.category} · {product.unit}</small></span><span>{money(product.stock)}</span><span>{money(product.price)}</span><ChevronRight size={20} /></button>{:else}<div class="empty">No products match your search.</div>{/each}</div></section>
      <section class="panel cart-panel"><h2>Current sale</h2><div class="cart-head"><span>Item</span><span>Qty</span><span>Unit price (RWF)</span><span>Subtotal (RWF)</span></div><div class="cart-lines">{#each cart as line}<div class="cart-row"><div class="product-name"><strong>{$products.find((p) => p.id === line.productId)?.name}</strong><small>{$products.find((p) => p.id === line.productId)?.category} · {$products.find((p) => p.id === line.productId)?.unit}</small></div><input class="qty-input" data-qty={line.productId} type="number" min="1" step="1" value={line.quantity} onchange={(e) => updateLine(line.productId, 'quantity', e.currentTarget.value)} onkeydown={(e) => { if (e.key === 'Enter') { e.preventDefault(); updateLine(line.productId, 'quantity', e.currentTarget.value); searchInput?.focus(); } }} aria-label="Quantity" /><div class="price-cell"><input type="number" min="0" step="1" value={line.unitPrice} onchange={(e) => updateLine(line.productId, 'unitPrice', e.currentTarget.value)} aria-label="Unit price" /><small>Today’s price: {rwf($products.find((p) => p.id === line.productId)?.price ?? 0)}</small></div><strong class="subtotal">{money(line.quantity * line.unitPrice)}</strong><button class="icon-button" aria-label="Remove item" onclick={() => removeLine(line.productId)}><Trash2 size={20} /></button></div>{:else}<div class="cart-empty">Choose a product to start a sale.</div>{/each}</div><div class="cart-bottom"><div class="total-line"><strong>Total</strong><strong>{rwf(total)}</strong></div><button class="primary end-sale" disabled={!cart.length} onclick={() => paymentOpen = true}>End sale <ArrowRight size={26} /></button></div></section>
      {#if paymentOpen}<section class="panel payment-panel"><div class="payment-title"><div><h2>Payment</h2><p>Collect the full amount to complete this sale.</p></div><button class="icon-button" aria-label="Close payment" onclick={() => paymentOpen = false}><X size={21} /></button></div><div class="payment-summary"><span>Amount due</span><strong>{rwf(total)}</strong></div><div class="payment-methods">{#each ['cash', 'momo', 'bank'] as method}<label><span class="method-label"><Wallet size={18} />{method === 'momo' ? 'MoMo' : method[0].toUpperCase() + method.slice(1)}</span><div class="money-input"><span>RWF</span><input type="number" min="0" step="1" value={payment[method as PaymentMethod]} oninput={(e) => payment = { ...payment, [method]: Math.max(0, Math.round(Number(e.currentTarget.value) || 0)) }} /></div></label>{/each}</div><div class="payment-foot"><div class="payment-summary remaining"><span>Remaining</span><strong>{rwf(remaining)}</strong></div><div class:enabled={canConfirm} class="slide-track" bind:this={sliderElement} onpointerdown={pointerDown} onpointermove={pointerMove} onpointerup={pointerUp} onpointercancel={pointerUp} role="button" tabindex="0" aria-label="Slide to confirm sale" onkeydown={(e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); void finishSale(); } }}><span class="slide-text">Slide to confirm sale</span><span class="slide-handle" style={`transform: translateX(${dragProgress * (sliderElement?.clientWidth ? sliderElement.clientWidth - 56 : 0)}px)`}><ArrowRight size={21} /></span></div><button class="text-action" disabled={!canConfirm} onclick={finishSale}>Or click to confirm</button></div></section>{/if}</div>
    {:else if page === 'inventory'}
      <div class="page-card"><div class="section-heading"><div><h2>Inventory</h2><p>Products, deliveries and supplier balances.</p></div><div class="actions"><button class="secondary" onclick={() => productDrawer = true}><Plus size={17} /> New product</button><button class="primary compact" onclick={() => { stockForm.productId = $products[0]?.id ?? ''; stockDrawer = true; }}><Plus size={17} /> Add stock</button></div></div><div class="tabs"><button class:chosen={inventoryTab === 'products'} onclick={() => inventoryTab = 'products'}>Products</button><button class:chosen={inventoryTab === 'history'} onclick={() => inventoryTab = 'history'}>Stock history</button><button class:chosen={inventoryTab === 'balances'} onclick={() => inventoryTab = 'balances'}>Supplier balances</button></div>{#if inventoryTab === 'products'}<div class="table-wrap"><table><thead><tr><th>Product</th><th>Category</th><th>Unit</th><th>In stock</th><th>Today’s price</th><th>Status</th></tr></thead><tbody>{#each $products as product}<tr><td class="strong">{product.name}</td><td>{product.category}</td><td>{product.unit}</td><td>{money(product.stock)}</td><td>{rwf(product.price)}</td><td><span class:warning={product.stock < 10} class="badge">{product.stock < 10 ? 'Low stock' : 'Active'}</span></td></tr>{/each}</tbody></table></div>{:else if inventoryTab === 'history'}<div class="table-wrap"><table><thead><tr><th>Date</th><th>Product</th><th>Quantity</th><th>Unit cost</th><th>Supplier</th><th>Paid</th></tr></thead><tbody>{#each $stockEntries as entry}<tr><td>{shortDate(entry.at)}</td><td class="strong">{entry.productName}</td><td>+{entry.quantity}</td><td>{rwf(entry.unitCost)}</td><td>{entry.supplier || '—'}</td><td>{rwf(entry.paid)}</td></tr>{:else}<tr><td colspan="6" class="empty-cell">No deliveries recorded yet.</td></tr>{/each}</tbody></table></div>{:else}<div class="table-wrap"><table><thead><tr><th>Supplier</th><th>Amount due</th></tr></thead><tbody>{#each balances as balance}<tr><td class="strong">{balance.supplier}</td><td>{rwf(balance.due)}</td></tr>{:else}<tr><td colspan="2" class="empty-cell">No supplier balances yet.</td></tr>{/each}</tbody></table></div>{/if}</div>
    {:else if page === 'sales'}
      <div class="page-card"><div class="section-heading"><div><h2>Sales history</h2><p>Every completed sale and its payment split.</p></div><button class="secondary" onclick={exportCsv}>Export CSV</button></div><div class="table-wrap"><table><thead><tr><th>Date & time</th><th>Sale</th><th>Items</th><th>Payment</th><th>Total</th><th>Sync</th></tr></thead><tbody>{#each $sales as sale}<tr><td>{shortDate(sale.at)}</td><td class="strong">#{sale.id.slice(0, 8)}</td><td>{sale.lines.map((line) => `${line.quantity} ${line.name}`).join(', ')}</td><td>{sale.payments.map((p) => p.method === 'momo' ? 'MoMo' : p.method).join(' + ')}</td><td class="strong">{rwf(sale.total)}</td><td><span class:warning={sale.sync === 'queued'} class="badge">{sale.sync === 'queued' ? 'Queued' : 'Synced'}</span></td></tr>{:else}<tr><td colspan="6" class="empty-cell">No sales yet.</td></tr>{/each}</tbody></table></div></div>
    {:else if page === 'expenses'}
      <div class="content-grid"><section class="page-card"><div class="section-heading"><div><h2>Record expense</h2><p>Keep daily operating costs accurate.</p></div></div><form class="form-grid" onsubmit={(e) => { e.preventDefault(); void submitExpense(); }}><label>Category<select bind:value={expenseForm.category}><option>Transport</option><option>Rent</option><option>Utilities</option><option>Wages</option><option>Loss</option><option>Other</option></select></label><label>Amount (RWF)<input type="number" min="1" step="1" bind:value={expenseForm.amount} required /></label><label class="wide">Description<input bind:value={expenseForm.description} placeholder="What was this for?" /></label><label>Payment account<select bind:value={expenseForm.method}><option value="cash">Cash</option><option value="momo">MoMo</option><option value="bank">Bank</option></select></label><button class="primary compact" disabled={working}>Save expense <ArrowRight size={18} /></button></form></section><section class="page-card"><h2>Recent expenses</h2><div class="simple-list">{#each $expenses as expense}<div><div><strong>{expense.category}</strong><small>{expense.description || shortDate(expense.at)}</small></div><strong>{rwf(expense.amount)}</strong></div>{:else}<p class="muted">No expenses yet.</p>{/each}</div></section></div>
    {:else if page === 'reports'}
      <div class="report-grid"><div class="metric"><span>Sales today</span><strong>{rwf(revenue)}</strong><small>{daySales.length} completed sales</small></div><div class="metric"><span>Cost of goods</span><strong>{rwf(cost)}</strong><small>FIFO cost when connected</small></div><div class="metric"><span>Expenses today</span><strong>{rwf(expenseTotal)}</strong><small>{dayExpenses.length} recorded expenses</small></div><div class="metric profit"><span>Estimated profit</span><strong>{profitVerified ? rwf(profit) : 'Pending cost'}</strong><small>{profitVerified ? 'Sales − cost − expenses' : 'Profit needs verified purchase costs'}</small></div><div class="page-card report-wide"><div class="section-heading"><div><h2>Payment collection</h2><p>Today’s sales by account.</p></div><button class="secondary" onclick={exportCsv}>Export CSV</button></div><div class="payment-totals">{#each ['cash', 'momo', 'bank'] as method}<div><span>{method === 'momo' ? 'MoMo' : method[0].toUpperCase() + method.slice(1)}</span><strong>{rwf(daySales.flatMap((s) => s.payments).filter((p) => p.method === method).reduce((sum, p) => sum + p.amount, 0))}</strong></div>{/each}</div>{#if isDemo}<p class="muted report-note">Demo mode is for interface review only. Its profit figure is withheld because purchase costs are not verified.</p>{/if}</div></div>
    {:else}<div class="page-card"><div class="section-heading"><div><h2>Activity log</h2><p>A clear timeline of changes and transactions.</p></div></div><div class="activity-list">{#each $activities as item}<div class="activity-row"><span class="activity-dot"></span><div><strong>{item.action}</strong><p>{item.detail}</p></div><time>{shortDate(item.at)}</time></div>{:else}<p class="muted">No activity yet.</p>{/each}</div></div>{/if}
    </main></div>
  {#if startDayOpen}<div class="overlay" role="presentation" onclick={(e) => { if (e.target === e.currentTarget) startDayOpen = false; }}><section class="drawer"><div class="drawer-head"><div><h2>{$businessDay?.date === today() && $businessDay.status === 'closed' ? 'Reopen day' : 'Start day'}</h2><p>{$businessDay?.date === today() && $businessDay.status === 'closed' ? 'Record why this business day is being reopened.' : 'Review today’s selling prices before taking sales.'}</p></div><button class="icon-button" aria-label="Close" onclick={() => startDayOpen = false}><X size={21} /></button></div><div class="drawer-scroll">{#if $businessDay?.date === today() && $businessDay.status === 'closed'}<div class="form-stack"><label>Reason<input bind:value={reopenReason} minlength="5" placeholder="Why is the day being reopened?" required /></label></div>{:else}<div class="price-list">{#each $products.filter((p) => p.active) as product}<label><span><strong>{product.name}</strong><small>{product.category} · {product.unit}</small></span><div class="money-input"><span>RWF</span><input type="number" min="0" step="1" bind:value={priceDraft[product.id]} /></div></label>{/each}</div>{/if}</div><div class="drawer-footer"><button class="primary" disabled={working} onclick={submitDay}>{$businessDay?.date === today() && $businessDay.status === 'closed' ? 'Reopen day' : 'Confirm prices and open day'} <ArrowRight size={19} /></button></div></section></div>{/if}
  {#if stockDrawer}<div class="overlay" role="presentation" onclick={(e) => { if (e.target === e.currentTarget) stockDrawer = false; }}><form class="drawer" onsubmit={(e) => { e.preventDefault(); void submitStock(); }}><div class="drawer-head"><div><h2>Add stock</h2><p>Record a new supplier delivery.</p></div><button type="button" class="icon-button" aria-label="Close" onclick={() => stockDrawer = false}><X size={21} /></button></div><div class="drawer-scroll form-stack"><label>Product<select bind:value={stockForm.productId} required>{#each $products as product}<option value={product.id}>{product.name} · {product.unit}</option>{/each}</select></label><div class="form-grid"><label>Quantity<input type="number" min="1" step="1" bind:value={stockForm.quantity} required /></label><label>Unit cost (RWF)<input type="number" min="0" step="1" bind:value={stockForm.unitCost} required /></label></div><label>Supplier<input bind:value={stockForm.supplier} placeholder="Supplier name" /></label><label>Amount paid now (RWF)<input type="number" min="0" step="1" bind:value={stockForm.paid} /></label><label>Note<input bind:value={stockForm.note} placeholder="Optional delivery note" /></label><div class="drawer-total"><span>Total cost</span><strong>{rwf(stockForm.quantity * stockForm.unitCost)}</strong></div></div><div class="drawer-footer"><button class="primary" disabled={working}>Save delivery <ArrowRight size={19} /></button></div></form></div>{/if}
  {#if productDrawer}<div class="overlay" role="presentation" onclick={(e) => { if (e.target === e.currentTarget) productDrawer = false; }}><form class="drawer" onsubmit={(e) => { e.preventDefault(); void submitProduct(); }}><div class="drawer-head"><div><h2>New product</h2><p>Keep names short and easy to find.</p></div><button type="button" class="icon-button" aria-label="Close" onclick={() => productDrawer = false}><X size={21} /></button></div><div class="drawer-scroll form-stack"><label>Product name<input bind:value={productForm.name} placeholder="Bismati" required /></label><label>Category<input bind:value={productForm.category} placeholder="Rice" required /></label><label>Unit<input bind:value={productForm.unit} placeholder="25 kg sack" required /></label><label>Suggested selling price (RWF)<input type="number" min="0" step="1" bind:value={productForm.price} /></label></div><div class="drawer-footer"><button class="primary" disabled={working}>Create product <ArrowRight size={19} /></button></div></form></div>{/if}
{/if}
